// Calcule la plage = mois calendaire precedent (format Gmail YYYY/M/D)
const now = new Date();
const firstThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const firstPrevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const fmt = (d) => `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
return [{ json: { after: fmt(firstPrevMonth), before: fmt(firstThisMonth) } }];

// Assemble tous les mails en un seul bloc texte pour le LLM.
const items = $input.all();
if (items.length === 0) {
  return [{ json: { blob: 'AUCUN MAIL trouve avec le label Veille le mois dernier.', count: 0 } }];
}
const blob = items.map((it, i) => {
  const j = it.json;
  const sujet = j.subject || j.Subject || '(sans sujet)';
  const date = j.date || j.internalDate || '';
  const corps = j.text || j.textAsHtml || j.snippet || '';
  // Lien direct vers le mail d'origine dans Gmail
  const lien = j.id ? `https://mail.google.com/mail/u/0/#all/${j.id}` : '';
  return `### MAIL ${i + 1}\nSujet: ${sujet}\nDate: ${date}\nLien du mail: ${lien}\nContenu:\n${corps}`;
}).join('\n\n---\n\n');
return [{ json: { blob, count: items.length } }];
